/* Finite portrait assembly and a scroll-bound floating original cover. */
(()=>{const grid=document.querySelector('#yb-grid'),edition=document.querySelector('#publication'),cover=document.querySelector('.yb-cover');if(!grid||!cover)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),animations=new Map(),seen=new WeakSet();let raf=0,queue=0;
const finish=el=>{animations.get(el)?.forEach(a=>a.cancel());animations.delete(el);el.classList.remove('yb-card-pending');};
const observer=new IntersectionObserver(entries=>{for(const entry of entries){const card=entry.target,summary=card.querySelector('summary');if(entry.isIntersecting&&!card.hidden&&!seen.has(card)&&!reduced.matches){seen.add(card);card.classList.remove('yb-card-pending');const index=+card.style.getPropertyValue('--slot')||0,sign=index%2?1:-1,mobile=innerWidth<650,initial=`perspective(1200px) translate3d(${sign*(mobile?45:140)}px,${mobile?130:210}px,${mobile?-260:-600}px) rotateX(-24deg) rotateY(${sign*(mobile?48:72)}deg) rotateZ(${sign*12}deg) scale(.55)`;const a=summary.animate([{transform:initial,opacity:.35},{transform:`perspective(1200px) translate3d(${sign*-12}px,-14px,35px) rotateY(${sign*-4}deg) scale(1.015)`,opacity:1,offset:.8},{transform:'none',opacity:1}],{duration:mobile?850:1100,delay:index%4*70,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'});animations.set(card,[a]);a.finished.then(()=>finish(card)).catch(()=>{});}}},{threshold:.06,rootMargin:'40px 0px 0px'});
function scan(){clearTimeout(queue);queue=setTimeout(()=>{[...grid.children].filter(e=>!e.hidden).forEach((card,index)=>{finish(card);card.style.setProperty('--slot',index);seen.delete(card);observer.unobserve(card);if(!reduced.matches){card.classList.add('yb-card-pending');observer.observe(card);}});},0);}
const mutations=new MutationObserver(scan);mutations.observe(grid,{subtree:false,attributes:false,childList:true});const visibility=new MutationObserver(scan);visibility.observe(grid,{subtree:true,attributes:true,attributeFilter:['hidden']});grid.addEventListener('focusin',e=>{const card=e.target.closest('.yb-person');if(card){seen.add(card);finish(card);}});
function draw(){raf=0;if(document.hidden||reduced.matches)return;const r=edition.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const p=Math.max(0,Math.min(1,(innerHeight-r.top)/(r.height+innerHeight)));cover.style.setProperty('--cover-y',`${35-90*p}px`);cover.style.setProperty('--cover-z',`${10-11*p}deg`);cover.style.setProperty('--cover-turn',`${-18+28*p}deg`);}
function request(){if(!raf&&!reduced.matches&&!document.hidden)raf=requestAnimationFrame(draw);}
addEventListener('scroll',request,{passive:true});addEventListener('resize',request);reduced.addEventListener('change',()=>{animations.forEach((_,e)=>finish(e));grid.querySelectorAll('.yb-card-pending').forEach(e=>e.classList.remove('yb-card-pending'));if(!reduced.matches)scan();else{cancelAnimationFrame(raf);raf=0;cover.removeAttribute('style');}});document.addEventListener('visibilitychange',()=>{if(document.hidden){animations.forEach((_,e)=>finish(e));cancelAnimationFrame(raf);raf=0;}else request();});addEventListener('pagehide',()=>{animations.forEach((_,e)=>finish(e));cancelAnimationFrame(raf);raf=0;});scan();request();
})();
